{"command":"cat > calcurse_clone.py <<'PY'
#!/usr/bin/env python3
"""A clean-room reimplementation of the observed calcurse command-line behavior.

This is intentionally self-contained and implements the documented/observed
non-interactive organizer features: plain text data files, iCalendar import and
export, queries, filters, and formatting.
"""
from __future__ import annotations

import calendar as _calendar
import datetime as _dt
import hashlib
import os
import re
import shutil
import sys
import tempfile
import time
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple, Iterable, Any, Set

VERSION = "4.8.2"
HELP_TEXT = """Usage:
calcurse [-D <directory>] [-C <directory>] [-c <calendar file>]
calcurse -Q [--from <date>] [--to <date>] [--days <number>]
calcurse -a | -d <date> | -d <number> | -n | -r[<number>] | -s[<date>] | -t[<number>]
calcurse -h | -v | --status | -G | -P | -g | -i <file> | -x[<format>] | --daemon

Operations in command line mode:
  -Q, --query   Print items in a given query range
  -G, --grep    Grep items from the data files
  -P, --purge   Read items and write them back
Query short forms:
-a, -d <date>|<number>, -n, -r[<number>], -s[<date>], -t<number>

Note that filter, format and day-range options affect input or output:
  --filter-*              Filter items loaded by -Q, -G, -P and -x
  --format-*              Rewrite output from -Q, -G and --dump-imported
  --from <date>           Limit day range of -Q.
  --to <date>             Limit day range of -Q.
  --days <number>         Limit day range of -Q.

  --limit, -l <number>    Limit number of query results
  --search, -S <regexp>   Match regular expression in queries
Consult the man page for details.

Miscellaneous:
  -c, --calendar <file>   The calendar data file to use
  -C, --confdir <dir>     The configuration directory to use
  --daemon                Run notification daemon in the background
  -D, --datadir <dir>     The data directory to use
  -g, --gc                Run the garbage collector
  -h, --help              Show this help text
  -i, --import <file>     Import iCal data from file
  -q, --quiet             Suppress import/export result message
  --read-only             Do not save configuration or data files
  --status                Display status of running instances
  -v, --version           Show version information
  -x, --export[<format>]  Export to stdout in ical (default) or pcal format

For more information, type '?' from within calcurse, or read the manpage.
Submit feature requests and suggestions to <misc@calcurse.org>.
Submit bug reports to <bugs@calcurse.org>.
"""

# ---------------------------------------------------------------------------
# Basic utilities

def eprint(s: str = "") -> None:
    sys.stderr.write(s + "\n")


def fatal(msg: str, rc: int = 1) -> int:
    eprint(msg)
    return rc


def sha1_text(s: str) -> str:
    return hashlib.sha1(s.encode("utf-8")).hexdigest()


def days_in_month(year: int, month: int) -> int:
    return _calendar.monthrange(year, month)[1]


def date_add_months(d: _dt.date, months: int) -> Optional[_dt.date]:
    y = d.year + (d.month - 1 + months) // 12
    m = (d.month - 1 + months) % 12 + 1
    dim = days_in_month(y, m)
    if d.day > dim:
        return None
    return _dt.date(y, m, d.day)


def storage_date(d: _dt.date) -> str:
    return d.strftime("%m/%d/%Y")


def storage_dt(dt: _dt.datetime) -> str:
    return dt.strftime("%m/%d/%Y @ %H:%M")


def parse_storage_date(s: str) -> _dt.date:
    m = re.match(r"^(\d{1,2})/(\d{1,2})/(\d{4})$", s.strip())
    if not m:
        raise ValueError("bad date")
    mo, da, yr = map(int, m.groups())
    return _dt.date(yr, mo, da)


def parse_storage_time(s: str) -> _dt.time:
    h, m = map(int, s.split(":"))
    return _dt.time(h, m)


def parse_storage_datetime(date_s: str, time_s: str) -> _dt.datetime:
    d = parse_storage_date(date_s)
    t = parse_storage_time(time_s)
    return _dt.datetime.combine(d, t)


WEEKDAY_NAMES = {
    "sun": 6, "sunday": 6,
    "mon": 0, "monday": 0,
    "tue": 1, "tuesday": 1,
    "wed": 2, "wednesday": 2,
    "thu": 3, "thursday": 3,
    "fri": 4, "friday": 4,
    "sat": 5, "saturday": 5,
}


def parse_input_date(s: str, input_fmt: int = 1) -> _dt.date:
    raw = s.strip()
    low = raw.lower()
    today = _dt.date.today()
    if low in ("today", "now"):
        return today
    if low == "tomorrow":
        return today + _dt.timedelta(days=1)
    if low == "yesterday":
        return today - _dt.timedelta(days=1)
    if low in WEEKDAY_NAMES:
        target = WEEKDAY_NAMES[low]
        delta = (target - today.weekday()) % 7
        return today + _dt.timedelta(days=delta)
    if input_fmt == 4:
        pat = r"^(\d{4})-(\d{1,2})-(\d{1,2})$"
        m = re.match(pat, raw)
        if not m:
            raise ValueError("bad date")
        y, mo, da = map(int, m.groups())
        return _dt.date(y, mo, da)
    parts = raw.split("/")
    if len(parts) != 3:
        raise ValueError("bad date")
    a, b, c = map(int, parts)
    if input_fmt == 1:
        mo, da, y = a, b, c
    elif input_fmt == 2:
        da, mo, y = a, b, c
    elif input_fmt == 3:
        y, mo, da = a, b, c
    else:
        raise ValueError("bad date")
    return _dt.date(y, mo, da)


def parse_filter_datetime(s: str, input_fmt: int) -> _dt.datetime:
    # Date arguments to filter options may be followed by HH:MM.
    raw = s.strip()
    m = re.match(r"^(.*)\s+(\d{1,2}:\d{2})$", raw)
    if m:
        d = parse_input_date(m.group(1), input_fmt)
        h, mi = map(int, m.group(2).split(":"))
        return _dt.datetime(d.year, d.month, d.day, h, mi)
    d = parse_input_date(raw, input_fmt)
    return _dt.datetime(d.year, d.month, d.day)


def format_output_date(d: _dt.date, fmt: str) -> str:
    # GNU strftime supports %D/%F here.  Keep a tiny fallback for portability.
    try:
        return d.strftime(fmt)
    except Exception:
        return d.strftime(fmt.replace("%D", "%m/%d/%y").replace("%F", "%Y-%m-%d"))


def unescape_format_arg(s: str) -> str:
    # calcurse format arguments interpret common C-style escapes.
    out = []
    i = 0
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s):
            c = s[i + 1]
            if c == "n":
                out.append("\n")
            elif c == "t":
                out.append("\t")
            elif c == "r":
                out.append("\r")
            elif c == "\\":
                out.append("\\")
            else:
                out.append(c)
            i += 2
        else:
            out.append(s[i])
            i += 1
    return "".join(out)


# ---------------------------------------------------------------------------
# Recurrence handling

@dataclass
class Recur:
    interval: int
    unit: str  # D,W,M,Y
    until: Optional[_dt.date] = None
    exceptions: List[_dt.date] = field(default_factory=list)
    monthdays: List[int] = field(default_factory=list)  # dN
    weekdays: List[int] = field(default_factory=list)   # calcurse wN encoding
    months: List[int] = field(default_factory=list)     # mN

    def clone_without_until(self) -> "Recur":
        return Recur(self.interval, self.unit, None, list(self.exceptions),
                     list(self.monthdays), list(self.weekdays), list(self.months))


DOW_ICAL_TO_CAL = {"SU": 0, "MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6}
CAL_TO_ICAL = {0: "SU", 1: "MO", 2: "TU", 3: "WE", 4: "TH", 5: "FR", 6: "SA"}


def py_to_cal_dow(py_weekday: int) -> int:
    # Python: Mon=0..Sun=6. calcurse encoding for unqualified weekdays: Sun=0, Mon=1...
    return (py_weekday + 1) % 7


def cal_to_py_dow(cal_dow: int) -> int:
    return (cal_dow - 1) % 7


def encode_byday_token(tok: str) -> int:
    m = re.match(r"^([+-]?\d+)?(SU|MO|TU|WE|TH|FR|SA)$", tok)
    if not m:
        raise ValueError("bad BYDAY")
    ord_s, day_s = m.groups()
    dow = DOW_ICAL_TO_CAL[day_s]
    if not ord_s:
        return dow
    n = int(ord_s)
    if n > 0:
        return n * 7 + dow
    return n * 7 - dow


def decode_wtoken(w: int) -> Tuple[Optional[int], int]:
    # Returns (ordinal, cal_dow); ordinal None means an unqualified weekday.
    if -6 <= w <= 6:
        return None, w
    if w > 0:
        return w // 7, w % 7
    a = -w
    return -(a // 7), a % 7


def wtoken_to_ical(w: int) -> str:
    ordn, dow = decode_wtoken(w)
    day = CAL_TO_ICAL[dow]
    if ordn is None:
        return day
    if ordn > 0:
        return f"+{ordn}{day}"
    return f"{ordn}{day}"


def parse_recur_spec(s: str) -> Recur:
    parts = s.strip().split()
    if not parts:
        raise ValueError("empty recur")
    m = re.match(r"^(\d+)([DWMY])$", parts[0])
    if not m:
        raise ValueError("bad recur")
    r = Recur(int(m.group(1)), m.group(2))
    i = 1
    if i < len(parts) and parts[i] == "->":
        if i + 1 >= len(parts):
            raise ValueError("bad until")
        r.until = parse_storage_date(parts[i + 1])
        i += 2
    while i < len(parts):
        tok = parts[i]
        if tok.startswith("!"):
            r.exceptions.append(parse_storage_date(tok[1:]))
        elif tok.startswith("d"):
            r.monthdays.append(int(tok[1:]))
        elif tok.startswith("w"):
            r.weekdays.append(int(tok[1:]))
        elif tok.startswith("m"):
            r.months.append(int(tok[1:]))
        i += 1
    return r


def recur_to_string(r: Recur) -> str:
    out = [f"{r.interval}{r.unit}"]
    if r.until:
        out.extend(["->", storage_date(r.until)])
    for ex in r.exceptions:
        out.append("!" + storage_date(ex))
    for d in r.monthdays:
        out.append("d" + str(d))
    for w in r.weekdays:
        out.append("w" + str(w))
    for m in r.months:
        out.append("m" + str(m))
    return " ".join(out)


def monthday_matches(day: _dt.date, vals: List[int]) -> bool:
    if not vals:
        return True
    dim = days_in_month(day.year, day.month)
    for v in vals:
        target = v if v > 0 else dim + 1 + v
        if day.day == target:
            return True
    return False


def weekday_ordinal_in_month(day: _dt.date) -> int:
    cal = py_to_cal_dow(day.weekday())
    # 1-based occurrence of this weekday in the month.
    pos = 1 + (day.day - 1) // 7
    dim = days_in_month(day.year, day.month)
    neg = - (1 + (dim - day.day) // 7)
    return pos, neg, cal


def weekday_ordinal_in_year(day: _dt.date) -> int:
    cal = py_to_cal_dow(day.weekday())
    count = 0
    d = _dt.date(day.year, 1, 1)
    while d <= day:
        if py_to_cal_dow(d.weekday()) == cal:
            count += 1
        d += _dt.timedelta(days=1)
    d = _dt.date(day.year, 12, 31)
    neg = 0
    while d >= day:
        if py_to_cal_dow(d.weekday()) == cal:
            neg -= 1
        d -= _dt.timedelta(days=1)
    return count, neg, cal


def weekday_matches(day: _dt.date, vals: List[int], scope: str) -> bool:
    if not vals:
        return True
    for w in vals:
        ordn, dow = decode_wtoken(w)
        if py_to_cal_dow(day.weekday()) != dow:
            continue
        if ordn is None:
            return True
        if scope == "year":
            pos, neg, _ = weekday_ordinal_in_year(day)
        else:
            pos, neg, _ = weekday_ordinal_in_month(day)
        if ordn == pos or ordn == neg:
            return True
    return False


def recur_occurs_on(r: Recur, start: _dt.date, day: _dt.date) -> bool:
    if day < start:
        return False
    if r.until and day > r.until:
        return False
    if day in set(r.exceptions):
        return False
    if r.months and day.month not in r.months:
        return False

    # Base frequency/interval.
    if r.unit == "D":
        diff = (day - start).days
        if diff < 0 or diff % r.interval != 0:
            return False
        # Extra BY* filters act as constraints.
        if r.monthdays and not monthday_matches(day, r.monthdays):
            return False
        if r.weekdays and not weekday_matches(day, r.weekdays, "month"):
            return False
        return True

    if r.unit == "W":
        start_monday = start - _dt.timedelta(days=start.weekday())
        day_monday = day - _dt.timedelta(days=day.weekday())
        weeks = (day_monday - start_monday).days // 7
        if weeks < 0 or weeks % r.interval != 0:
            return False
        if r.weekdays:
            if not weekday_matches(day, r.weekdays, "month"):
                return False
        elif day.weekday() != start.weekday():
            return False
        if r.monthdays and not monthday_matches(day, r.monthdays):
            return False
        return True

    if r.unit == "M":
        months = (day.year - start.year) * 12 + (day.month - start.month)
        if months < 0 or months % r.interval != 0:
            return False
        if r.monthdays and not monthday_matches(day, r.monthdays):
            return False
        if r.weekdays and not weekday_matches(day, r.weekdays, "month"):
            return False
        if not r.monthdays and not r.weekdays:
            return day.day == start.day
        return True

    if r.unit == "Y":
        years = day.year - start.year
        if years < 0 or years % r.interval != 0:
            return False
        if r.months:
            pass
        elif not r.monthdays and not r.weekdays and day.month != start.month:
            return False
        # For ordinal BYDAY in YEARLY with BYMONTH, RFC-style semantics are within the month;
        # otherwise ordinal weekdays are within the year.
        wscope = "month" if r.months else "year"
        if r.monthdays and not monthday_matches(day, r.monthdays):
            return False
        if r.weekdays and not weekday_matches(day, r.weekdays, wscope):
            return False
        if not r.monthdays and not r.weekdays:
            return day.day == start.day
        return True
    return False


def generate_recur_dates(r: Recur, start: _dt.date, until: Optional[_dt.date] = None,
                         count: Optional[int] = None, max_years: int = 250) -> List[_dt.date]:
    res: List[_dt.date] = []
    end = until or (start + _dt.timedelta(days=366 * max_years))
    d = start
    while d <= end:
        if recur_occurs_on(r, start, d):
            res.append(d)
            if count is not None and len(res) >= count:
                break
        d += _dt.timedelta(days=1)
    return res


# ---------------------------------------------------------------------------
# Data model and calcurse plain text files

@dataclass
class Item:
    kind: str  # event, apt, todo; recurrence determines recur-* type
    summary: str
    raw: str = ""
    note: Optional[str] = None
    note_content: Optional[str] = None
    recur: Optional[Recur] = None
    # event fields
    date: Optional[_dt.date] = None
    event_len: int = 1
    # appointment fields
    start: Optional[_dt.datetime] = None
    end: Optional[_dt.datetime] = None
    # todo fields
    priority: int = 0
    completed: bool = False

    def type_name(self) -> str:
        if self.kind == "todo":
            return "todo"
        if self.kind == "event":
            return "recur-event" if self.recur else "event"
        if self.kind == "apt":
            return "recur-apt" if self.recur else "apt"
        return self.kind

    def raw_text(self) -> str:
        return self.raw or item_to_raw(self)

    def hash(self) -> str:
        return sha1_text(self.raw_text())


def item_start_dt(it: Item) -> Optional[_dt.datetime]:
    if it.kind == "todo":
        return None
    if it.kind == "event":
        assert it.date
        return _dt.datetime.combine(it.date, _dt.time())
    return it.start


def item_end_dt(it: Item) -> Optional[_dt.datetime]:
    if it.kind == "todo":
        return None
    if it.kind == "event":
        assert it.date
        return _dt.datetime.combine(it.date, _dt.time(23, 59, 59))
    return it.end


def item_to_raw(it: Item) -> str:
    if it.kind == "todo":
        sign = "-" if it.completed else ""
        s = f"[{sign}{it.priority}]"
        if it.note:
            s += ">" + it.note
        if it.summary:
            s += " " + it.summary
        return s
    if it.kind == "event":
        assert it.date
        s = f"{storage_date(it.date)} [{it.event_len}]"
        if it.recur:
            s += " {" + recur_to_string(it.recur) + "}"
        if it.note:
            s += " >" + it.note
        s += " " + it.summary
        return s
    assert it.start and it.end
    s = f"{storage_dt(it.start)} -> {storage_dt(it.end)}"
    if it.recur:
        s += " {" + recur_to_string(it.recur) + "}"
    if it.note:
        s += ">" + it.note
    s += " |" + it.summary
    return s


def parse_todo_line(line: str) -> Optional[Item]:
    m = re.match(r"^\[(-?)(\d+)\](?:>([0-9a-fA-F]{40}))?(?:\s?(.*))$", line)
    if not m:
        return None
    sign, pr, note, summary = m.groups()
    it = Item("todo", summary or "", raw=line, note=note, priority=int(pr), completed=(sign == "-"))
    return it


def parse_apt_line(line: str) -> Optional[Item]:
    m = re.match(r"^(\d{1,2}/\d{1,2}/\d{4}) @ (\d{2}:\d{2}) -> (\d{1,2}/\d{1,2}/\d{4}) @ (\d{2}:\d{2})(.*)$", line)
    if not m:
        return None
    d1, t1, d2, t2, rest = m.groups()
    if "|" not in rest:
        return None
    meta, summary = rest.split("|", 1)
    recur = None
    rm = re.search(r"\{([^}]*)\}", meta)
    if rm:
        try:
            recur = parse_recur_spec(rm.group(1))
        except Exception:
            recur = None
    nm = re.search(r">([0-9a-fA-F]{40})", meta)
    note = nm.group(1) if nm else None
    try:
        start = parse_storage_datetime(d1, t1)
        end = parse_storage_datetime(d2, t2)
    except Exception:
        return None
    return Item("apt", summary, raw=line, note=note, recur=recur, start=start, end=end)


def parse_event_line(line: str) -> Optional[Item]:
    m = re.match(r"^(\d{1,2}/\d{1,2}/\d{4}) \[(\d+)\](.*)$", line)
    if not m:
        return None
    ds, ln, rest = m.groups()
    try:
        date = parse_storage_date(ds)
    except Exception:
        return None
    remain = rest.strip()
    recur = None
    note = None
    if remain.startswith("{"):
        end = remain.find("}")
        if end >= 0:
            try:
                recur = parse_recur_spec(remain[1:end])
            except Exception:
                recur = None
            remain = remain[end+1:].strip()
    if remain.startswith(">") and len(remain) >= 41:
        cand = remain[1:41]
        if re.match(r"^[0-9a-fA-F]{40}$", cand):
            note = cand
            remain = remain[41:].strip()
    summary = remain
    return Item("event", summary, raw=line, note=note, recur=recur, date=date, event_len=int(ln))


def parse_apts_file(path: str) -> List[Item]:
    items: List[Item] = []
    if not os.path.exists(path):
        return items
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for raw in f:
            line = raw.rstrip("\n")
            if not line:
                continue
            it = parse_apt_line(line) or parse_event_line(line)
            if it:
                items.append(it)
    return items


def parse_todo_file(path: str) -> List[Item]:
    items: List[Item] = []
    if not os.path.exists(path):
        return items
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for raw in f:
            line = raw.rstrip("\n")
            if not line:
                continue
            it = parse_todo_line(line)
            if it:
                items.append(it)
    return items


def load_notes(items: List[Item], notes_dir: str) -> None:
    for it in items:
        if it.note:
            p = os.path.join(notes_dir, it.note)
            try:
                with open(p, "r", encoding="utf-8", errors="replace") as f:
                    it.note_content = f.read()
            except Exception:
                it.note_content = None


def todo_sort_key(it: Item):
    pr = it.priority if it.priority != 0 else 10
    return (1 if it.completed else 0, pr, it.summary)


def cal_grep_category(it: Item) -> int:
    tn = it.type_name()
    return {"recur-event": 1, "recur-apt": 2, "apt": 3, "event": 4}.get(tn, 9)


def cal_sort_key(it: Item):
    cat = cal_grep_category(it)
    if it.kind == "event":
        sd = _dt.datetime.combine(it.date or _dt.date.min, _dt.time())
        ed = sd
    else:
        sd = it.start or _dt.datetime.min
        ed = it.end or sd
    return (cat, sd, ed, it.summary, it.raw_text())


def write_data_files(calendar_path: str, todo_path: str, items: List[Item]) -> None:
    cal_items = [it for it in items if it.kind != "todo"]
    todos = [it for it in items if it.kind == "todo"]
    cal_items.sort(key=cal_sort_key)
    todos.sort(key=todo_sort_key)
    os.makedirs(os.path.dirname(calendar_path) or ".", exist_ok=True)
    os.makedirs(os.path.dirname(todo_path) or ".", exist_ok=True)
    with open(calendar_path, "w", encoding="utf-8") as f:
        for it in cal_items:
            it.raw = item_to_raw(it)
            f.write(it.raw + "\n")
    with open(todo_path, "w", encoding="utf-8") as f:
        for it in todos:
            it.raw = item_to_raw(it)
            f.write(it.raw + "\n")


# ---------------------------------------------------------------------------
# Paths, config, and arguments

@dataclass
class Paths:
    data_dir: str
    conf_dir: str
    calendar: str
    todo: str
    notes: str
    conf: str


def default_data_dir() -> str:
    x = os.environ.get("XDG_DATA_HOME")
    if x is not None:
        return os.path.join(x, "calcurse")
    home = os.environ.get("HOME", "")
    return os.path.join(home, ".local", "share", "calcurse")


def default_conf_dir() -> str:
    x = os.environ.get("XDG_CONFIG_HOME")
    if x is not None:
        return os.path.join(x, "calcurse")
    home = os.environ.get("HOME", "")
    return os.path.join(home, ".config", "calcurse")


def build_paths(opts: "Options") -> Paths:
    if opts.datadir:
        data = opts.datadir
        conf = opts.confdir if opts.confdir else opts.datadir
    else:
        data = default_data_dir()
        conf = opts.confdir if opts.confdir else default_conf_dir()
    cal = opts.calendar if opts.calendar else os.path.join(data, "apts")
    if opts.calendar and not os.path.isabs(cal):
        cal = os.path.abspath(cal)
    return Paths(data, conf, cal, os.path.join(data, "todo"), os.path.join(data, "notes"), os.path.join(conf, "conf"))


def ensure_files(paths: Paths, read_only: bool, need_calendar: bool = True, need_todo: bool = True,
                 create_conf: bool = True) -> Optional[str]:
    if read_only:
        if need_calendar and not os.path.exists(paths.calendar):
            return "io.c: 569: failed to open appointment file"
        if need_todo and not os.path.exists(paths.todo):
            return "io.c: 569: failed to open appointment file"
        return None
    # Alternate calendar file must already exist; observed -c does not create it.
    if need_calendar and paths.calendar and os.path.basename(paths.calendar) != "apts" and not os.path.exists(paths.calendar):
        return f"io.c: 189: {paths.calendar} does not exist"
    try:
        if need_calendar:
            os.makedirs(os.path.dirname(paths.calendar) or ".", exist_ok=True)
            if not os.path.exists(paths.calendar):
                open(paths.calendar, "a", encoding="utf-8").close()
        if need_todo:
            os.makedirs(os.path.dirname(paths.todo) or ".", exist_ok=True)
            if not os.path.exists(paths.todo):
                open(paths.todo, "a", encoding="utf-8").close()
        if create_conf:
            os.makedirs(paths.conf_dir, exist_ok=True)
            if not os.path.exists(paths.conf):
                open(paths.conf, "a", encoding="utf-8").close()
    except PermissionError as e:
        # Match common fatal shape for unwritable XDG roots.
        return f"FATAL ERROR: could not create {os.path.dirname(str(e.filename) if e.filename else paths.data_dir)}: Permission denied"
    except Exception as e:
        return str(e)
    return None


def read_config(paths: Paths) -> Tuple[int, str]:
    input_fmt = 1
    output_fmt = "%D"
    try:
        with open(paths.conf, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = k.strip(); v = v.strip()
                if k == "format.inputdate":
                    try:
                        input_fmt = int(v)
                    except Exception:
                        pass
                elif k == "format.outputdate":
                    output_fmt = v
    except Exception:
        pass
    return input_fmt, output_fmt


@dataclass
class Options:
    datadir: Optional[str] = None
    confdir: Optional[str] = None
    calendar: Optional[str] = None
    read_only: bool = False
    quiet: bool = False
    operation: Optional[str] = None  # help,version,status,daemon,gc,import,export,query,grep,purge,next,interactive
    import_file: Optional[str] = None
    export_format: str = "ical"
    dump_imported: bool = False
    export_uid: bool = False
    input_datefmt_override: Optional[int] = None
    output_datefmt_override: Optional[str] = None
    # query/day options
    from_s: Optional[str] = None
    to_s: Optional[str] = None
    days: Optional[int] = None
    limit: Optional[int] = None
    # filters
    filter_type: Optional[str] = None
    filter_pattern: Optional[str] = None
    filter_hash: Optional[str] = None
    filter_invert: bool = False
    filter_completed: bool = False
    filter_uncompleted: bool = False
    filter_priority: Optional[int] = None
    start_from: Optional[str] = None
    start_to: Optional[str] = None
    start_after: Optional[str] = None
    start_before: Optional[str] = None
    end_from: Optional[str] = None
    end_to: Optional[str] = None
    end_after: Optional[str] = None
    end_before: Optional[str] = None
    # format strings
    fmt_apt: Optional[str] = None
    fmt_recur_apt: Optional[str] = None
    fmt_event: Optional[str] = None
    fmt_recur_event: Optional[str] = None
    fmt_todo: Optional[str] = None


def set_operation(opts: Options, op: str) -> None:
    # Keep the first main operation; multiple operations are invalid in real calcurse,
    # but most valid invocations use one.  Short-form queries override operation only if absent.
    if opts.operation is None:
        opts.operation = op
    else:
        # Mark a conflict using a sentinel.  Directory/filter/format options do not call this.
        if opts.operation != op:
            opts.operation = "invalid"


def require_arg(argv: List[str], idx: int, opt: str) -> Tuple[str, int]:
    if idx + 1 >= len(argv):
        raise ValueError(f"{opt} requires an argument")
    return argv[idx + 1], idx + 2


def parse_args(argv: List[str]) -> Tuple[Options, List[str], Optional[str]]:
    opts = Options()
    leftovers: List[str] = []
    i = 0
    try:
        while i < len(argv):
            a = argv[i]
            if a == "--":
                leftovers.extend(argv[i+1:]); break
            if not a.startswith("-") or a == "-":
                leftovers.append(a); i += 1; continue
            if a.startswith("--"):
                nameval = a[2:]
                if "=" in nameval:
                    name, val = nameval.split("=", 1)
                    has_val = True
                else:
                    name, val, has_val = nameval, None, False
                def need() -> str:
                    nonlocal i, val, has_val
                    if has_val:
                        return val or ""
                    if i + 1 >= len(argv):
                        raise ValueError(f"--{name} requires an argument")
                    i += 1
                    return argv[i]
                if name in ("help",): set_operation(opts, "help")
                elif name in ("version",): set_operation(opts, "version")
                elif name == "status": set_operation(opts, "status")
                elif name == "daemon": set_operation(opts, "daemon")
                elif name == "query": set_operation(opts, "query")
                elif name == "grep": set_operation(opts, "grep")
                elif name == "purge": set_operation(opts, "purge")
                elif name == "filter": set_operation(opts, "purge")
                elif name == "gc": set_operation(opts, "gc")
                elif name == "appointment":
                    set_operation(opts, "query"); opts.filter_type = "cal"; opts.from_s = "today"; opts.days = 1
                elif name == "next": set_operation(opts, "next")
                elif name == "quiet": opts.quiet = True
                elif name == "read-only": opts.read_only = True
                elif name == "dump-imported": opts.dump_imported = True
                elif name == "export-uid": opts.export_uid = True
                elif name in ("datadir",): opts.datadir = need()
                elif name in ("confdir",): opts.confdir = need()
                elif name in ("calendar",): opts.calendar = need()
                elif name == "day":
                    v = need(); set_operation(opts, "query"); opts.filter_type = "cal"
                    if re.match(r"^[+-]?\d+$", v): opts.days = int(v)
                    else: opts.from_s = v; opts.days = 1
                elif name == "import": opts.import_file = need(); set_operation(opts, "import")
                elif name == "export":
                    set_operation(opts, "export")
                    if has_val:
                        opts.export_format = val or "ical"
                    else:
                        opts.export_format = "ical"
                elif name == "input-datefmt": opts.input_datefmt_override = int(need())
                elif name == "output-datefmt": opts.output_datefmt_override = need()
                elif name == "limit": opts.limit = int(need())
                elif name == "search": opts.filter_pattern = need()
                elif name == "from": opts.from_s = need()
                elif name == "to": opts.to_s = need()
                elif name == "days": opts.days = int(need())
                elif name == "range":
                    set_operation(opts, "query"); opts.filter_type = "cal"; opts.days = int(val) if has_val and val not in (None, "") else 1
                elif name == "startday":
                    set_operation(opts, "query"); opts.filter_type = "cal"; opts.from_s = val if has_val and val != "" else "today"; opts.days = 1
                elif name == "todo":
                    set_operation(opts, "query"); opts.filter_type = "todo"
                    if has_val and val != "":
                        pr = int(val); opts.filter_priority = pr
                        if pr == 0: opts.filter_completed = True
                        else: opts.filter_uncompleted = True
                    else:
                        opts.filter_uncompleted = True
                elif name == "filter-invert": opts.filter_invert = True
                elif name == "filter-type": opts.filter_type = need()
                elif name == "filter-pattern": opts.filter_pattern = need()
                elif name == "filter-hash": opts.filter_hash = need()
                elif name == "filter-start-from": opts.start_from = need()
                elif name == "filter-start-to": opts.start_to = need()
                elif name == "filter-start-after": opts.start_after = need()
                elif name == "filter-start-before": opts.start_before = need()
                elif name == "filter-start-range":
                    v = need(); p = v.split(",", 1); opts.start_from = p[0]; opts.start_to = p[1] if len(p) > 1 else p[0]
                elif name == "filter-end-from": opts.end_from = need()
                elif name == "filter-end-to": opts.end_to = need()
                elif name == "filter-end-after": opts.end_after = need()
                elif name == "filter-end-before": opts.end_before = need()
                elif name == "filter-end-range":
                    v = need(); p = v.split(",", 1); opts.end_from = p[0]; opts.end_to = p[1] if len(p) > 1 else p[0]
                elif name == "filter-priority": opts.filter_priority = int(need())
                elif name == "filter-completed": opts.filter_completed = True
                elif name == "filter-uncompleted": opts.filter_uncompleted = True
                elif name == "format-apt": opts.fmt_apt = unescape_format_arg(need())
                elif name == "format-recur-apt": opts.fmt_recur_apt = unescape_format_arg(need())
                elif name == "format-event": opts.fmt_event = unescape_format_arg(need())
                elif name == "format-recur-event": opts.fmt_recur_event = unescape_format_arg(need())
                elif name == "format-todo": opts.fmt_todo = unescape_format_arg(need())
                else:
                    return opts, leftovers, f"unknown option: --{name}"
                i += 1
                continue

            # Short options.  Support optional arguments for r/s/t/x only attached.
            if a in ("-h",): set_operation(opts, "help"); i += 1; continue
            if a in ("-v",): set_operation(opts, "version"); i += 1; continue
            if a == "-Q": set_operation(opts, "query"); i += 1; continue
            if a == "-G": set_operation(opts, "grep"); i += 1; continue
            if a == "-P" or a == "-F": set_operation(opts, "purge"); i += 1; continue
            if a == "-g": set_operation(opts, "gc"); i += 1; continue
            if a == "-a": set_operation(opts, "query"); opts.filter_type = "cal"; opts.from_s = "today"; opts.days = 1; i += 1; continue
            if a == "-n": set_operation(opts, "next"); i += 1; continue
            if a == "-q": opts.quiet = True; i += 1; continue
            if a.startswith("-D"):
                if len(a) > 2: opts.datadir = a[2:]; i += 1
                else: opts.datadir, i = require_arg(argv, i, "-D")
                continue
            if a.startswith("-C"):
                if len(a) > 2: opts.confdir = a[2:]; i += 1
                else: opts.confdir, i = require_arg(argv, i, "-C")
                continue
            if a.startswith("-c"):
                if len(a) > 2: opts.calendar = a[2:]; i += 1
                else: opts.calendar, i = require_arg(argv, i, "-c")
                continue
            if a.startswith("-d"):
                if len(a) > 2: v = a[2:]; i += 1
                else: v, i = require_arg(argv, i, "-d")
                set_operation(opts, "query"); opts.filter_type = "cal"
                if re.match(r"^[+-]?\d+$", v): opts.days = int(v)
                else: opts.from_s = v; opts.days = 1
                continue
            if a.startswith("-i"):
                if len(a) > 2: opts.import_file = a[2:]; i += 1
                else: opts.import_file, i = require_arg(argv, i, "-i")
                set_operation(opts, "import"); continue
            if a.startswith("-l"):
                if len(a) > 2: opts.limit = int(a[2:]); i += 1
                else:
                    v, i = require_arg(argv, i, "-l"); opts.limit = int(v)
                continue
            if a.startswith("-S"):
                if len(a) > 2: opts.filter_pattern = a[2:]; i += 1
                else: opts.filter_pattern, i = require_arg(argv, i, "-S")
                continue
            if a.startswith("-r"):
                set_operation(opts, "query"); opts.filter_type = "cal"
                opts.days = int(a[2:]) if len(a) > 2 else 1
                i += 1; continue
            if a.startswith("-s"):
                set_operation(opts, "query"); opts.filter_type = "cal"; opts.from_s = a[2:] if len(a) > 2 else "today"; opts.days = 1
                i += 1; continue
            if a.startswith("-t"):
                set_operation(opts, "query"); opts.filter_type = "todo"
                if len(a) > 2:
                    pr = int(a[2:]); opts.filter_priority = pr
                    if pr == 0: opts.filter_completed = True
                    else: opts.filter_uncompleted = True
                else:
                    opts.filter_uncompleted = True
                i += 1; continue
            if a.startswith("-x"):
                set_operation(opts, "export")
                opts.export_format = a[2:] if len(a) > 2 else "ical"
                i += 1; continue
            return opts, leftovers, f"unknown option: {a}"
    except Exception as ex:
        return opts, leftovers, str(ex)
    return opts, leftovers, None


# ---------------------------------------------------------------------------
# iCalendar import/export

@dataclass
class ICalProp:
    name: str
    params: Dict[str, str]
    value: str
    raw_name: str


def split_ical_line(line: str) -> Optional[Tuple[str, str]]:
    inq = False
    esc = False
    for i, ch in enumerate(line):
        if ch == '"' and not esc:
            inq = not inq
        if ch == ":" and not inq:
            return line[:i], line[i+1:]
        esc = (ch == "\\" and not esc)
        if ch != "\\":
            esc = False
    return None


def parse_prop(line: str) -> Optional[ICalProp]:
    sp = split_ical_line(line)
    if sp is None:
        return None
    left, value = sp
    pieces = []
    cur = []
    inq = False
    for ch in left:
        if ch == '"':
            inq = not inq
        if ch == ";" and not inq:
            pieces.append("".join(cur)); cur = []
        else:
            cur.append(ch)
    pieces.append("".join(cur))
    name = pieces[0].upper()
    params: Dict[str, str] = {}
    for p in pieces[1:]:
        if "=" in p:
            k, v = p.split("=", 1)
            params[k.upper()] = v.strip('"')
    return ICalProp(name=name, params=params, value=value, raw_name=left)


def has_unescaped_text_special(s: str) -> bool:
    esc = False
    for ch in s:
        if esc:
            esc = False; continue
        if ch == "\\":
            esc = True; continue
        if ch in ",;":
            return True
    return False


def ical_text_unescape(s: str, summary: bool = False) -> str:
    out = []
    i = 0
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s):
            c = s[i+1]
            if c in ("n", "N"):
                out.append(" " if summary else "\n")
            elif c in (",", ";", "\\"):
                out.append(c)
            else:
                out.append(c)
            i += 2
        else:
            out.append(s[i]); i += 1
    return "".join(out)


def ical_text_escape(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\": out.append("\\\\")
        elif ch == "\n": out.append("\\n")
        elif ch == ",": out.append("\\,")
        elif ch == ";": out.append("\\;")
        else: out.append(ch)
    return "".join(out)


def parse_ical_date_value(value: str, is_date: bool) -> Any:
    v = value.strip()
    if is_date:
        if not re.match(r"^\d{8}$", v):
            raise ValueError("bad date")
        return _dt.date(int(v[:4]), int(v[4:6]), int(v[6:8]))
    if v.endswith("Z"):
        v = v[:-1]
    if not re.match(r"^\d{8}T\d{6}$", v):
        raise ValueError("bad datetime")
    return _dt.datetime(int(v[:4]), int(v[4:6]), int(v[6:8]), int(v[9:11]), int(v[11:13]), int(v[13:15]))


def format_ical_date(d: _dt.date) -> str:
    return d.strftime("%Y%m%d")


def format_ical_dt(dt: _dt.datetime) -> str:
    return dt.strftime("%Y%m%dT%H%M%S")


def parse_duration(s: str) -> _dt.timedelta:
    m = re.match(r"^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$", s)
    if not m:
        raise ValueError("bad duration")
    w, d, h, mi, sec = [int(x) if x else 0 for x in m.groups()]
    return _dt.timedelta(weeks=w, days=d, hours=h, minutes=mi, seconds=sec)


def duration_has_time(s: str) -> bool:
    return "T" in s


def duration_to_ical(td: _dt.timedelta) -> str:
    total = int(td.total_seconds())
    if total < 0: total = 0
    days, rem = divmod(total, 86400)
    hours, rem = divmod(rem, 3600)
    mins, secs = divmod(rem, 60)
    return f"P{days}DT{hours}H{mins}M{secs}S"


def note_from_parts(description: Optional[str], location: Optional[str], comment: Optional[str], imports: List[str]) -> Optional[str]:
    has_desc = description is not None
    meta_lines: List[str] = []
    if location is not None:
        meta_lines.append("Location: " + location)
    if comment is not None:
        lines = comment.split("\n")
        if lines:
            meta_lines.append("Comment: " + lines[0])
            for l in lines[1:]:
                meta_lines.append("    " + l)
        else:
            meta_lines.append("Comment: ")
    for imp in imports:
        meta_lines.append("Import: " + imp)
    if not has_desc and not meta_lines:
        return None
    out = ""
    if has_desc:
        out += description + "\n"
    if meta_lines:
        out += "-- \n"
        out += "\n".join(meta_lines) + "\n"
    return out


def write_note_if_needed(content: Optional[str], notes_dir: str) -> Optional[str]:
    if content is None:
        return None
    h = sha1_text(content)
    os.makedirs(notes_dir, exist_ok=True)
    with open(os.path.join(notes_dir, h), "w", encoding="utf-8") as f:
        f.write(content)
    return h


def parse_rrule(value: str) -> Tuple[Recur, Optional[int], Optional[str]]:
    parts: Dict[str, str] = {}
    for p in value.split(";"):
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        parts[k.upper()] = v
    freq = parts.get("FREQ", "").upper()
    unitmap = {"DAILY": "D", "WEEKLY": "W", "MONTHLY": "M", "YEARLY": "Y"}
    if freq not in unitmap:
        raise ValueError("unsupported freq")
    interval = int(parts.get("INTERVAL", "1") or "1")
    r = Recur(interval, unitmap[freq])
    if "BYMONTHDAY" in parts:
        r.monthdays = [int(x) for x in parts["BYMONTHDAY"].split(",") if x]
    if "BYDAY" in parts:
        r.weekdays = [encode_byday_token(x) for x in parts["BYDAY"].split(",") if x]
    if "BYMONTH" in parts:
        r.months = [int(x) for x in parts["BYMONTH"].split(",") if x]
    count = int(parts["COUNT"]) if "COUNT" in parts else None
    until_val = parts.get("UNTIL")
    return r, count, until_val


def item_occurrence_dates_for_count(r: Recur, start_date: _dt.date, start_time: Optional[_dt.time],
                                    count: Optional[int], until_val: Optional[str], is_date: bool) -> Optional[_dt.date]:
    temp = r.clone_without_until()
    if count is not None:
        dates = generate_recur_dates(temp, start_date, count=count)
        return dates[-1] if dates else start_date
    if until_val:
        if is_date:
            if not re.match(r"^\d{8}$", until_val):
                raise ValueError("bad until")
            until_date = parse_ical_date_value(until_val, True)
            return until_date
        else:
            if until_val.endswith("Z"):
                uv = until_val[:-1]
            else:
                uv = until_val
            if not re.match(r"^\d{8}T\d{6}$", uv):
                raise ValueError("bad until")
            until_dt = parse_ical_date_value(until_val, False)
            # Last occurrence whose start datetime is <= UNTIL.
            dates = generate_recur_dates(temp, start_date, until=until_dt.date())
            good = []
            st = start_time or _dt.time()
            for d in dates:
                if _dt.datetime.combine(d, st) <= until_dt:
                    good.append(d)
            return good[-1] if good else None
    return None


def build_item_from_props(kind: str, props: List[ICalProp], notes_dir: str) -> Tuple[Optional[Item], Optional[str]]:
    # Returns (item, error).  A non-None error means the item is skipped.
    d: Dict[str, List[ICalProp]] = {}
    for p in props:
        d.setdefault(p.name, []).append(p)
    def one(name: str) -> Optional[ICalProp]:
        vals = d.get(name, [])
        return vals[0] if vals else None
    # Duplicate LOCATION is treated as invalid by the observed importer.
    if len(d.get("LOCATION", [])) > 1:
        return None, "duplicate LOCATION"
    for p in props:
        if p.name in ("SUMMARY", "DESCRIPTION", "COMMENT", "LOCATION"):
            if has_unescaped_text_special(p.value):
                return None, "unescaped text special"
    try:
        summary_prop = one("SUMMARY")
        summary = ical_text_unescape(summary_prop.value, summary=True) if summary_prop else ""
        desc_prop = one("DESCRIPTION")
        comment_prop = one("COMMENT")
        loc_prop = one("LOCATION")
        desc = ical_text_unescape(desc_prop.value) if desc_prop else None
        comment = ical_text_unescape(comment_prop.value) if comment_prop else None
        location = ical_text_unescape(loc_prop.value) if loc_prop else None
        imports: List[str] = []

        if kind == "VTODO":
            pr_prop = one("PRIORITY")
            priority = int(pr_prop.value) if pr_prop else 0
            if priority < 0 or priority > 9:
                return None, "bad priority"
            completed = False
            st = one("STATUS")
            if st and st.value.upper() == "COMPLETED":
                completed = True
            note_content = note_from_parts(desc, location, comment, imports)
            note_hash = write_note_if_needed(note_content, notes_dir)
            it = Item("todo", summary, note=note_hash, note_content=note_content,
                      priority=priority, completed=completed)
            it.raw = item_to_raw(it)
            return it, None

        # VEVENT
        dtstart = one("DTSTART")
        if not dtstart or dtstart.value == "":
            return None, "missing start"
        is_date = dtstart.params.get("VALUE", "").upper() == "DATE"
        if "TZID" in dtstart.params:
            imports.append("TZID=" + dtstart.params["TZID"])
        start_val = parse_ical_date_value(dtstart.value, is_date)
        dtend_p = one("DTEND")
        dur_p = one("DURATION")
        if dtend_p and dur_p:
            return None, "both end and duration"
        rrule_p = one("RRULE")
        exdate_props = d.get("EXDATE", [])
        if exdate_props and not rrule_p:
            return None, "exdate without rrule"

        recur: Optional[Recur] = None
        if rrule_p:
            recur, count, until_val = parse_rrule(rrule_p.value)
        # End/duration.
        if is_date:
            start_date: _dt.date = start_val
            if dur_p:
                if duration_has_time(dur_p.value):
                    return None, "bad date duration"
                delta = parse_duration(dur_p.value)
                days = max(1, int(delta.days))
                end_date = start_date + _dt.timedelta(days=days)
            elif dtend_p:
                end_is_date = dtend_p.params.get("VALUE", "").upper() == "DATE"
                if not end_is_date:
                    return None, "bad dtend type"
                end_date = parse_ical_date_value(dtend_p.value, True)
                if end_date < start_date:
                    return None, "end before start"
            else:
                end_date = start_date + _dt.timedelta(days=1)
            # Multi-day all-day events are converted to recurring one-day events.
            event_recur = recur
            if (end_date - start_date).days > 1 and recur is None:
                event_recur = Recur(1, "D", end_date - _dt.timedelta(days=1))
                imports.append("multi-day event changed to one-day event")
            if recur:
                until = item_occurrence_dates_for_count(recur, start_date, None, count, until_val, True)
                recur.until = until
            if exdate_props and event_recur:
                for ep in exdate_props:
                    ex_is_date = ep.params.get("VALUE", "").upper() == "DATE"
                    if not ex_is_date:
                        return None, "bad exdate type"
                    for val in ep.value.split(","):
                        event_recur.exceptions.append(parse_ical_date_value(val, True))
            note_content = note_from_parts(desc, location, comment, imports)
            note_hash = write_note_if_needed(note_content, notes_dir)
            it = Item("event", summary, note=note_hash, note_content=note_content,
                      date=start_date, event_len=1, recur=event_recur)
            it.raw = item_to_raw(it)
            return it, None
        else:
            start_dt: _dt.datetime = start_val
            if dur_p:
                delta = parse_duration(dur_p.value)
                end_dt = start_dt + delta
            elif dtend_p:
                end_is_date = dtend_p.params.get("VALUE", "").upper() == "DATE"
                if end_is_date:
                    return None, "bad dtend type"
                end_dt = parse_ical_date_value(dtend_p.value, False)
            else:
                end_dt = start_dt
            if end_dt < start_dt:
                return None, "end before start"
            # Storage has minute precision; truncate seconds.
            start_dt = start_dt.replace(second=0, microsecond=0)
            end_dt = end_dt.replace(second=0, microsecond=0)
            if recur:
                until = item_occurrence_dates_for_count(recur, start_dt.date(), start_dt.time(), count, until_val, False)
                recur.until = until
            if exdate_props and recur:
                for ep in exdate_props:
                    ex_is_date = ep.params.get("VALUE", "").upper() == "DATE"
                    if ex_is_date:
                        return None, "bad exdate type"
                    for val in ep.value.split(","):
                        recur.exceptions.append(parse_ical_date_value(val, False).date())
            note_content = note_from_parts(desc, location, comment, imports)
            note_hash = write_note_if_needed(note_content, notes_dir)
            it = Item("apt", summary, note=note_hash, note_content=note_content,
                      start=start_dt, end=end_dt, recur=recur)
            it.raw = item_to_raw(it)
            return it, None
    except Exception as ex:
        return None, str(ex)


def import_ical(filename: str, paths: Paths, opts: Options, formats: Dict[str, str]) -> int:
    if filename != "-" and not os.path.exists(filename):
        return fatal("io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...")
    # Import creates data files; with --read-only original fails if files are missing.
    err = ensure_files(paths, opts.read_only, need_calendar=True, need_todo=True, create_conf=False)
    if err:
        return fatal(err)
    try:
        if filename == "-":
            lines = sys.stdin.read().splitlines()
        else:
            with open(filename, "r", encoding="utf-8", errors="replace") as f:
                lines = f.read().splitlines()
    except Exception:
        return fatal("io.c: 1278: FATAL ERROR: the input file cannot be accessed, Aborting...")
    line_count = len(lines)
    imported: List[Item] = []
    skipped = 0
    cur_kind: Optional[str] = None
    cur_props: List[ICalProp] = []
    bad_item = False
    for line in lines:
        if line.startswith((" ", "\t")) and cur_props:
            # Continuation line (not used by bundled fixtures, but harmless).
            cur_props[-1].value += line[1:]
            continue
        p = parse_prop(line)
        if p is None:
            if cur_kind in ("VEVENT", "VTODO"):
                bad_item = True
            continue
        if p.name == "BEGIN" and p.value.upper() in ("VEVENT", "VTODO"):
            if cur_kind is not None:
                skipped += 1
            cur_kind = p.value.upper(); cur_props = []; bad_item = False
            continue
        if p.name == "END" and p.value.upper() in ("VEVENT", "VTODO"):
            if cur_kind == p.value.upper():
                if bad_item:
                    skipped += 1
                else:
                    it, err = build_item_from_props(cur_kind, cur_props, paths.notes)
                    if it is None:
                        skipped += 1
                    else:
                        imported.append(it)
                cur_kind = None; cur_props = []; bad_item = False
            continue
        if p.name == "END" and p.value.upper() == "VCALENDAR":
            if cur_kind is not None:
                skipped += 1
                cur_kind = None
            continue
        if cur_kind in ("VEVENT", "VTODO"):
            cur_props.append(p)
    if cur_kind is not None:
        skipped += 1

    # Append to existing data and save sorted.
    existing = parse_apts_file(paths.calendar) + parse_todo_file(paths.todo)
    all_items = existing + imported
    write_data_files(paths.calendar, paths.todo, all_items)

    if opts.dump_imported:
        load_notes(imported, paths.notes)
        # Dump in the order imported, using grep/dump defaults (raw unless format set).
        for it in imported:
            sys.stdout.write(format_item(it, formats, context_day=None, default_raw=True))
    apps = sum(1 for it in imported if it.kind == "apt")
    events = sum(1 for it in imported if it.kind == "event")
    todos = sum(1 for it in imported if it.kind == "todo")
    if not opts.quiet:
        sys.stdout.write(f"Import process report: {line_count:04d} lines read\n")
        sys.stdout.write(f"{apps} {'app' if apps == 1 else 'apps'} / {events} {'event' if events == 1 else 'events'} / {todos} {'todo' if todos == 1 else 'todos'} / {skipped} skipped\n")
    if skipped:
        fd, logpath = tempfile.mkstemp(prefix="calcurse_log.", dir=tempfile.gettempdir(), text=True)
        os.close(fd)
        sys.stderr.write("\nSome items could not be imported.\n")
        sys.stderr.write(f"See {logpath} for details.\n")
        return 1
    return 0


def parse_note_for_export(content: Optional[str]) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    if content is None:
        return None, None, None
    # Return description, location, comment.  Import: lines are intentionally not exported.
    if "-- \n" in content:
        desc_part, meta = content.split("-- \n", 1)
        # desc_part includes its trailing newline if present.
        if desc_part == "":
            desc = None
        else:
            desc = desc_part[:-1] if desc_part.endswith("\n") else desc_part
        location = None
        comment_lines: List[str] = []
        active_comment = False
        for line in meta.splitlines():
            if line.startswith("Location: "):
                location = line[len("Location: "):]
                active_comment = False
            elif line.startswith("Comment: "):
                comment_lines = [line[len("Comment: "):]]
                active_comment = True
            elif line.startswith("    ") and active_comment:
                comment_lines.append(line[4:])
            else:
                active_comment = False
        comment = "\n".join(comment_lines) if comment_lines else None
        return desc, location, comment
    else:
        # Entire note is a description, including an empty one-line description.
        desc = content[:-1] if content.endswith("\n") else content
        return desc, None, None


def export_rrule(r: Recur, is_event: bool, start_time: Optional[_dt.time]) -> str:
    freq = {"D": "DAILY", "W": "WEEKLY", "M": "MONTHLY", "Y": "YEARLY"}[r.unit]
    parts = ["FREQ=" + freq]
    if r.interval != 1:
        parts.append("INTERVAL=" + str(r.interval))
    if r.until:
        if is_event:
            parts.append("UNTIL=" + format_ical_date(r.until))
        else:
            st = start_time or _dt.time()
            parts.append("UNTIL=" + format_ical_dt(_dt.datetime.combine(r.until, st)))
    if r.months:
        parts.append("BYMONTH=" + ",".join(str(x) for x in r.months))
    if r.monthdays:
        parts.append("BYMONTHDAY=" + ",".join(str(x) for x in r.monthdays))
    if r.weekdays:
        parts.append("BYDAY=" + ",".join(wtoken_to_ical(w) for w in r.weekdays))
    return "RRULE:" + ";".join(parts)


def export_ical(items: List[Item], paths: Paths, opts: Options) -> None:
    sys.stdout.write("BEGIN:VCALENDAR\nVERSION:2.0\n")
    sys.stdout.write(f"PRODID:-//calcurse//NONSGML v{VERSION}//EN\n")
    cal_items = [it for it in items if it.kind != "todo"]
    todos = [it for it in items if it.kind == "todo"]
    cal_items.sort(key=cal_sort_key)
    todos.sort(key=todo_sort_key)
    for it in cal_items:
        sys.stdout.write("BEGIN:VEVENT\n")
        if opts.export_uid:
            sys.stdout.write("UID:" + it.hash() + "\n")
        if it.kind == "event":
            assert it.date
            sys.stdout.write("DTSTART;VALUE=DATE:" + format_ical_date(it.date) + "\n")
            if it.recur:
                sys.stdout.write(export_rrule(it.recur, True, None) + "\n")
                if it.recur.exceptions:
                    sys.stdout.write("EXDATE:" + ",".join(format_ical_date(x) for x in it.recur.exceptions) + "\n")
        else:
            assert it.start and it.end
            sys.stdout.write("DTSTART:" + format_ical_dt(it.start) + "\n")
            dur = it.end - it.start
            if int(dur.total_seconds()) > 0:
                sys.stdout.write("DURATION:" + duration_to_ical(dur) + "\n")
            if it.recur:
                sys.stdout.write(export_rrule(it.recur, False, it.start.time()) + "\n")
                if it.recur.exceptions:
                    sys.stdout.write("EXDATE:" + ",".join(format_ical_dt(_dt.datetime.combine(x, it.start.time())) for x in it.recur.exceptions) + "\n")
        sys.stdout.write("SUMMARY:" + ical_text_escape(it.summary) + "\n")
        desc, loc, com = parse_note_for_export(it.note_content)
        if desc is not None:
            sys.stdout.write("DESCRIPTION:" + ical_text_escape(desc) + "\n")
        if loc is not None:
            sys.stdout.write("LOCATION:" + ical_text_escape(loc) + "\n")
        if com is not None:
            sys.stdout.write("COMMENT:" + ical_text_escape(com) + "\n")
        sys.stdout.write("END:VEVENT\n")
    for it in todos:
        sys.stdout.write("BEGIN:VTODO\n")
        if opts.export_uid:
            sys.stdout.write("UID:" + it.hash() + "\n")
        sys.stdout.write("PRIORITY:" + str(it.priority) + "\n")
        sys.stdout.write("SUMMARY:" + ical_text_escape(it.summary) + "\n")
        desc, loc, com = parse_note_for_export(it.note_content)
        if desc is not None:
            sys.stdout.write("DESCRIPTION:" + ical_text_escape(desc) + "\n")
        if loc is not None:
            sys.stdout.write("LOCATION:" + ical_text_escape(loc) + "\n")
        if com is not None:
            sys.stdout.write("COMMENT:" + ical_text_escape(com) + "\n")
        if it.completed:
            sys.stdout.write("STATUS:COMPLETED\n")
        sys.stdout.write("END:VTODO\n")
    sys.stdout.write("END:VCALENDAR\n")


def export_pcal(items: List[Item]) -> None:
    sys.stdout.write("# calcurse pcal export\n\n")
    sys.stdout.write("# =======\n# options\n# =======\n")
    sys.stdout.write("opt -A -K -l -m -F Monday\n")
    sys.stdout.write("# Display week number (i.e. 1-52) on every Monday\n")
    sys.stdout.write("all monday in all week %w\n\n\n")
    sys.stdout.write("# =============\n# Recur. Events\n# =============\n")
    sys.stdout.write("# (pcal does not support from..until dates specification\n\n")
    for it in sorted([x for x in items if x.type_name() == "recur-event"], key=cal_sort_key):
        sys.stdout.write(f"{it.date.strftime('%b')} {it.date.day:02d}  {it.summary}\n")
    sys.stdout.write("\n# ======\n# Events\n# ======\n\n")
    for it in sorted([x for x in items if x.type_name() == "event"], key=cal_sort_key):
        sys.stdout.write(f"{it.date.strftime('%b')} {it.date.day:02d}  {it.summary}\n")
    sys.stdout.write("\n# ==============\n# Recur. Apoints\n# ==============\n")
    sys.stdout.write("# (pcal does not support from..until dates specification\n\n")
    for it in sorted([x for x in items if x.type_name() == "recur-apt"], key=cal_sort_key):
        sys.stdout.write(f"{it.start.strftime('%b')} {it.start.day:02d}  ({it.start.strftime('%H:%M')} -> {it.end.strftime('%H:%M')}) {it.summary}\n")
    sys.stdout.write("\n# ============\n# Appointments\n# ============\n")
    for it in sorted([x for x in items if x.type_name() == "apt"], key=cal_sort_key):
        sys.stdout.write(f"{it.start.strftime('%b')} {it.start.day:02d}  ({it.start.strftime('%H:%M')} -> {it.end.strftime('%H:%M')}) {it.summary}\n")
    sys.stdout.write("\n#\n# Todos\n#\n")
    for it in sorted([x for x in items if x.kind == "todo"], key=todo_sort_key):
        sys.stdout.write(f"note all  {it.priority}. {it.summary}\n")


# ---------------------------------------------------------------------------
# Filtering, formatting, and query printing

TYPE_EXPANSIONS = {
    "cal": ["event", "apt", "recur-event", "recur-apt"],
    "recur": ["recur-event", "recur-apt"],
}


def selected_types(s: Optional[str]) -> Optional[Set[str]]:
    if not s:
        return None
    out: Set[str] = set()
    for part in s.split(","):
        part = part.strip()
        if not part:
            continue
        if part in TYPE_EXPANSIONS:
            out.update(TYPE_EXPANSIONS[part])
        else:
            out.add(part)
    return out


def item_matches_filters(it: Item, opts: Options, input_fmt: int) -> bool:
    ok = True
    types = selected_types(opts.filter_type)
    if types is not None and it.type_name() not in types:
        ok = False
    if ok and opts.filter_pattern:
        try:
            if re.search(opts.filter_pattern, it.summary) is None:
                ok = False
        except re.error:
            ok = False
    if ok and opts.filter_hash:
        neg = opts.filter_hash.startswith("!")
        pref = opts.filter_hash[1:] if neg else opts.filter_hash
        hmatch = it.hash().startswith(pref)
        if neg:
            hmatch = not hmatch
        if not hmatch:
            ok = False
    if ok and it.kind == "todo":
        if opts.filter_priority is not None and it.priority != opts.filter_priority:
            ok = False
        if opts.filter_completed and not it.completed:
            ok = False
        if opts.filter_uncompleted and it.completed:
            ok = False
    if ok and it.kind != "todo":
        sd = item_start_dt(it); ed = item_end_dt(it)
        assert sd and ed
        try:
            if opts.start_from and sd < parse_filter_datetime(opts.start_from, input_fmt): ok = False
            if opts.start_to and sd > parse_filter_datetime(opts.start_to, input_fmt): ok = False
            if opts.start_after and sd <= parse_filter_datetime(opts.start_after, input_fmt): ok = False
            if opts.start_before and sd >= parse_filter_datetime(opts.start_before, input_fmt): ok = False
            if opts.end_from and ed < parse_filter_datetime(opts.end_from, input_fmt): ok = False
            if opts.end_to and ed > parse_filter_datetime(opts.end_to, input_fmt): ok = False
            if opts.end_after and ed <= parse_filter_datetime(opts.end_after, input_fmt): ok = False
            if opts.end_before and ed >= parse_filter_datetime(opts.end_before, input_fmt): ok = False
        except Exception:
            ok = False
    if opts.filter_invert:
        ok = not ok
    return ok


def default_formats(query: bool) -> Dict[str, str]:
    if query:
        return {
            "apt": " - %S -> %E\n\t%m\n",
            "recur-apt": " - %S -> %E\n\t%m\n",
            "event": " * %m\n",
            "recur-event": " * %m\n",
            "todo": "%p. %m\n",
        }
    return {"apt": "%(raw)", "recur-apt": "%(raw)", "event": "%(raw)", "recur-event": "%(raw)", "todo": "%(raw)"}


def build_formats(opts: Options, query: bool) -> Dict[str, str]:
    f = default_formats(query)
    if opts.fmt_apt is not None: f["apt"] = opts.fmt_apt
    if opts.fmt_recur_apt is not None: f["recur-apt"] = opts.fmt_recur_apt
    if opts.fmt_event is not None: f["event"] = opts.fmt_event
    if opts.fmt_recur_event is not None: f["recur-event"] = opts.fmt_recur_event
    if opts.fmt_todo is not None: f["todo"] = opts.fmt_todo
    return f


def epoch(dt: _dt.datetime) -> int:
    return int(time.mktime(dt.timetuple()))


def continuation_start(it: Item, day: Optional[_dt.date]) -> str:
    if it.kind != "apt" or not it.start:
        return ""
    if day is not None and it.start.date() < day:
        return "..:.."
    return it.start.strftime("%H:%M")


def continuation_end(it: Item, day: Optional[_dt.date]) -> str:
    if it.kind != "apt" or not it.end:
        return ""
    if day is not None and it.end.date() > day and it.end.time() != _dt.time(0, 0):
        return "..:.."
    return it.end.strftime("%H:%M")


def format_duration_seconds(total: int, fmt: str) -> str:
    neg = total < 0
    if neg:
        total_abs = -total
    else:
        total_abs = total
    days, rem = divmod(total_abs, 86400)
    hours, rem = divmod(rem, 3600)
    mins, secs = divmod(rem, 60)
    out = []
    i = 0
    while i < len(fmt):
        if fmt[i] == "%" and i + 1 < len(fmt):
            j = i + 1
            nopad = False; elastic = False
            if j < len(fmt) and fmt[j] == "-":
                nopad = True; j += 1
            if j < len(fmt) and fmt[j] == "E":
                elastic = True; j += 1
            if j < len(fmt):
                c = fmt[j]
                val: Optional[int] = None
                if c == "d": val = days
                elif c == "H": val = (total_abs // 3600 if elastic else hours)
                elif c == "M": val = (total_abs // 60 if elastic else mins)
                elif c == "S": val = (total_abs if elastic else secs)
                if val is not None:
                    s = str(val) if nopad else f"{val:02d}"
                    if neg and not out:
                        s = "-" + s
                    out.append(s); i = j + 1; continue
        out.append(fmt[i]); i += 1
    return "".join(out)


def extended_spec(it: Item, name: str, arg: Optional[str], context_day: Optional[_dt.date]) -> str:
    if name == "raw":
        return it.raw_text()
    if name == "hash":
        return it.hash()
    if name in ("duration", "remaining"):
        if it.kind != "apt" or not it.start or not it.end:
            return ""
        seconds = int((it.end - it.start).total_seconds()) if name == "duration" else int((it.start - _dt.datetime.now()).total_seconds())
        if arg is None or arg == "":
            return str(seconds)
        return format_duration_seconds(seconds, arg)
    if name in ("start", "end"):
        if it.kind != "apt" or not it.start or not it.end:
            return ""
        dt = it.start if name == "start" else it.end
        if arg in (None, "", "epoch"):
            return str(epoch(dt))
        if arg == "default":
            return continuation_start(it, context_day) if name == "start" else continuation_end(it, context_day)
        return dt.strftime(arg)
    return ""


def note_N(it: Item) -> str:
    if not it.note:
        return "\tNo note file found\n"
    content = it.note_content
    if content is None:
        return "\tNo note file found\n"
    lines = content.splitlines()
    if content.endswith("\n") and not lines:
        lines = [""]
    out = ""
    for line in lines:
        out += "\t" + line + "\n"
    out += "\n"
    return out


def format_item(it: Item, formats: Dict[str, str], context_day: Optional[_dt.date], default_raw: bool = False) -> str:
    typ = it.type_name()
    fmt = formats.get(typ, "%(raw)" if default_raw else "")
    out: List[str] = []
    i = 0
    while i < len(fmt):
        if fmt[i] == "%":
            if i + 1 < len(fmt) and fmt[i+1] == "%":
                out.append("%"); i += 2; continue
            if i + 1 < len(fmt) and fmt[i+1] == "(":
                end = fmt.find(")", i+2)
                if end != -1:
                    inside = fmt[i+2:end]
                    if ":" in inside:
                        name, arg = inside.split(":", 1)
                    else:
                        name, arg = inside, None
                    out.append(extended_spec(it, name, arg, context_day)); i = end + 1; continue
            if i + 1 < len(fmt):
                c = fmt[i+1]
                val = ""
                if it.kind == "todo":
                    if c == "m": val = it.summary
                    elif c == "p": val = str(it.priority)
                    elif c == "n": val = it.note or "(null)"
                    elif c == "N": val = note_N(it)
                elif it.kind == "event":
                    if c == "m": val = it.summary
                    elif c == "n": val = it.note or "(null)"
                    elif c == "N": val = note_N(it)
                elif it.kind == "apt":
                    if c == "m": val = it.summary
                    elif c == "n": val = it.note or "(null)"
                    elif c == "N": val = note_N(it)
                    elif c == "S": val = continuation_start(it, context_day)
                    elif c == "E": val = continuation_end(it, context_day)
                    elif c == "s" and it.start: val = str(epoch(it.start))
                    elif c == "e" and it.end: val = str(epoch(it.end))
                    elif c == "d" and it.start and it.end: val = str(int((it.end - it.start).total_seconds()))
                    elif c == "r" and it.start:
                        sec = int((it.start - _dt.datetime.now()).total_seconds())
                        # Match the rough H:MM shape; negative modulo behavior is not critical.
                        h = int(sec / 3600)
                        m = int((sec % 3600) / 60)
                        if sec < 0:
                            m = -int(((-sec) % 3600) / 60)
                        val = f"{h}:{m:02d}" if m >= 0 else f"{h}:{m:03d}"
                out.append(val); i += 2; continue
        out.append(fmt[i]); i += 1
    return "".join(out)


@dataclass
class Occurrence:
    item: Item
    day: _dt.date
    occ_start: Optional[_dt.datetime] = None
    occ_end: Optional[_dt.datetime] = None


def occurrence_item(occ: Occurrence) -> Item:
    it = occ.item
    if it.kind == "apt" and occ.occ_start is not None and occ.occ_end is not None:
        # A lightweight copy with occurrence start/end for formatting.
        return Item("apt", it.summary, raw=it.raw_text(), note=it.note, note_content=it.note_content,
                    recur=it.recur, start=occ.occ_start, end=occ.occ_end)
    if it.kind == "event" and occ.occ_start is not None:
        return Item("event", it.summary, raw=it.raw_text(), note=it.note, note_content=it.note_content,
                    recur=it.recur, date=occ.occ_start.date(), event_len=it.event_len)
    return it


def item_occurrences_in_range(it: Item, start_day: _dt.date, end_day: _dt.date) -> List[Occurrence]:
    res: List[Occurrence] = []
    if it.kind == "todo":
        return res
    if it.kind == "event":
        assert it.date
        dates: List[_dt.date]
        if it.recur:
            scan_start = max(it.date, start_day)
            scan_end = end_day
            d = scan_start
            dates = []
            while d <= scan_end:
                if recur_occurs_on(it.recur, it.date, d):
                    dates.append(d)
                d += _dt.timedelta(days=1)
        else:
            dates = [it.date] if start_day <= it.date <= end_day else []
        for d in dates:
            res.append(Occurrence(it, d, _dt.datetime.combine(d, _dt.time()), None))
        return res
    # Appointment; recurring appointment start dates may overlap multiple display days.
    assert it.start and it.end
    duration = it.end - it.start
    scan_start = start_day - _dt.timedelta(days=max(0, duration.days + 2))
    scan_end = end_day
    start_dates: List[_dt.date] = []
    if it.recur:
        d = max(it.start.date(), scan_start)
        while d <= scan_end:
            if recur_occurs_on(it.recur, it.start.date(), d):
                start_dates.append(d)
            d += _dt.timedelta(days=1)
    else:
        start_dates = [it.start.date()]
    for sd in start_dates:
        occ_start = _dt.datetime.combine(sd, it.start.time())
        occ_end = occ_start + duration
        d = max(start_day, occ_start.date())
        while d <= end_day:
            day_start = _dt.datetime.combine(d, _dt.time())
            day_end = day_start + _dt.timedelta(days=1)
            if occ_start < day_end and occ_end > day_start:
                res.append(Occurrence(it, d, occ_start, occ_end))
            d += _dt.timedelta(days=1)
    return res


def query_range(opts: Options, input_fmt: int) -> Tuple[_dt.date, _dt.date]:
    today = _dt.date.today()
    if opts.from_s:
        start = parse_input_date(opts.from_s, input_fmt)
    else:
        start = today
    if opts.to_s:
        end = parse_input_date(opts.to_s, input_fmt)
    elif opts.days is not None:
        n = opts.days
        if n >= 0:
            end = start + _dt.timedelta(days=max(n, 1) - 1)
        else:
            end = start
            start = start + _dt.timedelta(days=n + 1)
    else:
        end = start
    if end < start:
        start, end = end, start
    return start, end


def print_todos(todos: List[Item], formats: Dict[str, str], completed_header: bool) -> None:
    if not todos:
        return
    sys.stdout.write("completed tasks:\n" if completed_header else "to do:\n")
    for it in todos:
        sys.stdout.write(format_item(it, formats, None))


def run_query(items: List[Item], opts: Options, input_fmt: int, output_fmt: str, formats: Dict[str, str]) -> int:
    start, end = query_range(opts, input_fmt)
    # Filter all items first.
    matching = [it for it in items if item_matches_filters(it, opts, input_fmt)]
    todos = sorted([it for it in matching if it.kind == "todo"], key=todo_sort_key)
    cal_items = [it for it in matching if it.kind != "todo"]
    include_todos = selected_types(opts.filter_type) is None or "todo" in (selected_types(opts.filter_type) or set())
    include_cal = selected_types(opts.filter_type) is None or bool((selected_types(opts.filter_type) or set()) & {"event", "apt", "recur-event", "recur-apt"})
    printed_any = False
    count = 0
    limit = opts.limit
    if include_todos and todos:
        sys.stdout.write("completed tasks:\n" if (opts.filter_completed and not opts.filter_uncompleted) else "to do:\n")
        for it in todos:
            if limit is None or count < limit:
                sys.stdout.write(format_item(it, formats, None))
            count += 1
        printed_any = True
    if include_cal:
        day = start
        first_day_printed = False
        while day <= end:
            occs: List[Occurrence] = []
            for it in cal_items:
                occs.extend(item_occurrences_in_range(it, day, day))
            if occs:
                if printed_any and not first_day_printed:
                    sys.stdout.write("\n")
                elif first_day_printed:
                    sys.stdout.write("\n")
                sys.stdout.write(format_output_date(day, output_fmt) + ":\n")
                # Events alphabetically, then appointments by time/end/summary.
                evs = [o for o in occs if o.item.kind == "event"]
                aps = [o for o in occs if o.item.kind == "apt"]
                evs.sort(key=lambda o: (o.item.summary, o.item.raw_text()))
                aps.sort(key=lambda o: (o.occ_start or _dt.datetime.min, o.occ_end or _dt.datetime.min, o.item.summary))
                for occ in evs + aps:
                    oit = occurrence_item(occ)
                    if limit is None or count < limit:
                        sys.stdout.write(format_item(oit, formats, day))
                    count += 1
                first_day_printed = True
                printed_any = True
            day += _dt.timedelta(days=1)
    return 0


def run_grep(items: List[Item], opts: Options, input_fmt: int, formats: Dict[str, str]) -> int:
    matching = [it for it in items if item_matches_filters(it, opts, input_fmt)]
    todos = sorted([it for it in matching if it.kind == "todo"], key=todo_sort_key)
    cal = sorted([it for it in matching if it.kind != "todo"], key=cal_sort_key)
    for it in todos + cal:
        sys.stdout.write(format_item(it, formats, None, default_raw=True))
        # The raw default has no newline in the format string; calcurse raw items include line separation.
        if formats[it.type_name()] == "%(raw)":
            sys.stdout.write("\n")
    return 0


def run_purge(items: List[Item], paths: Paths, opts: Options, input_fmt: int) -> int:
    kept = [it for it in items if not item_matches_filters(it, opts, input_fmt)]
    if not opts.read_only:
        write_data_files(paths.calendar, paths.todo, kept)
    return 0


def run_next(items: List[Item]) -> int:
    now = _dt.datetime.now().replace(second=0, microsecond=0)
    horizon = now + _dt.timedelta(hours=24)
    best: Optional[Tuple[_dt.datetime, Item]] = None
    for it in items:
        if it.kind != "apt":
            continue
        # Search today/tomorrow recurring occurrences.
        for occ in item_occurrences_in_range(it, now.date(), horizon.date()):
            oit = occurrence_item(occ)
            if not oit.start:
                continue
            if now <= oit.start <= horizon:
                if best is None or oit.start < best[0]:
                    best = (oit.start, oit)
    if best:
        dt, it = best
        mins = int((dt - now).total_seconds() // 60)
        h, m = divmod(max(0, mins), 60)
        sys.stdout.write("next appointment:\n")
        sys.stdout.write(f"   [{h:02d}:{m:02d}] {it.summary}\n")
    return 0


def garbage_collect(paths: Paths, items: List[Item]) -> int:
    used = {it.note for it in items if it.note}
    if os.path.isdir(paths.notes):
        for name in os.listdir(paths.notes):
            p = os.path.join(paths.notes, name)
            if os.path.isfile(p) and name not in used:
                try:
                    os.unlink(p)
                except Exception:
                    pass
    return 0


# ---------------------------------------------------------------------------
# Main

def load_all(paths: Paths) -> List[Item]:
    items = parse_apts_file(paths.calendar) + parse_todo_file(paths.todo)
    load_notes(items, paths.notes)
    return items


def main(argv: List[str]) -> int:
    opts, leftovers, perr = parse_args(argv)
    if perr:
        return fatal("args.c: 880: invalid argument combination")
    if leftovers:
        return fatal("args.c: 880: invalid argument combination")
    if opts.operation == "invalid":
        return fatal("args.c: 880: invalid argument combination")
    if opts.operation == "help":
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts.operation == "version":
        sys.stdout.write(f"calcurse {VERSION} -- text-based organizer\n\n")
        sys.stdout.write("Copyright (c) 2004-2023 calcurse Development Team.\n")
        sys.stdout.write("This is free software; see the source for copying conditions.\n")
        return 0
    paths = build_paths(opts)
    if opts.operation == "status":
        sys.stdout.write("calcurse is not running\n")
        return 0
    if opts.operation == "daemon":
        return 0
    if opts.operation is None:
        # Minimal non-interactive fallback: create the usual files and exit.
        err = ensure_files(paths, opts.read_only)
        if err: return fatal(err)
        return 0

    # Operations below use configuration unless overridden.
    # Import intentionally does not require/create conf in observed alternate-calendar case,
    # but reading a missing conf is harmless.
    input_fmt, output_fmt = read_config(paths)
    if opts.input_datefmt_override is not None:
        input_fmt = opts.input_datefmt_override
    if opts.output_datefmt_override is not None:
        output_fmt = opts.output_datefmt_override

    if opts.operation == "import":
        formats = build_formats(opts, query=False)
        return import_ical(opts.import_file or "-", paths, opts, formats)

    # Other data operations require data files.
    err = ensure_files(paths, opts.read_only, need_calendar=True, need_todo=True, create_conf=True)
    if err:
        return fatal(err)
    items = load_all(paths)

    if opts.operation == "gc":
        return garbage_collect(paths, items)
    if opts.operation == "export":
        fmt = opts.export_format or "ical"
        if fmt not in ("ical", "pcal"):
            return fatal(f"args.c: 631: invalid export format: {fmt}")
        filtered = [it for it in items if item_matches_filters(it, opts, input_fmt)]
        if fmt == "ical": export_ical(filtered, paths, opts)
        else: export_pcal(filtered)
        return 0
    if opts.operation == "grep":
        return run_grep(items, opts, input_fmt, build_formats(opts, query=False))
    if opts.operation == "purge":
        return run_purge(items, paths, opts, input_fmt)
    if opts.operation == "next":
        return run_next(items)
    if opts.operation == "query":
        return run_query(items, opts, input_fmt, output_fmt, build_formats(opts, query=True))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        sys.exit(0)
